html {
  background: white;
}

body {
  font-family: "Lato", Helvetica, Arial, sans-serif;
  font-weight: 400;
  background: white;
  margin: 50px 0 100px;
  letter-spacing: .3px;
  color: #39424B;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  text-transform: none;
  margin: 0;
}

h1 {
  font-family: "Josefin Sans", Helvetica, Arial, sans-serif;
  font-weight: 700;
  font-size: 40px;
  letter-spacing: 1px;
}

h2 {
  font-family: "Josefin Sans", Helvetica, Arial, sans-serif;
  font-weight: 300;
  font-size: 16px;
  letter-spacing: .5px;
}

h3 {
  font-family: "Lato", Helvetica, Arial, sans-serif;
  font-weight: 300;
  font-size: 14px;
  letter-spacing: .4px;
}

h3.bold {
  font-weight: 700;
}

h4 {
  font-family: "Lato", Helvetica, Arial, sans-serif;
  font-weight: 300;
  font-size: 12px;
}

h4.bold {
  font-weight: 700;
}

h5 {
  font-family: "Lato", Helvetica, Arial, sans-serif;
  font-weight: 300;
  font-size: 11px;
}

h5.italic {
  font-style: italic;
}

h6 {
  font-family: "Lato", Helvetica, Arial, sans-serif;
  font-weight: 400;
  font-size: 10px;
}

a {
  color: inherit;
  text-decoration: inherit;
}

a:hover {
  color: #2895F1;
}

a .fa-external-link {
  font-size: 10px;
  vertical-align: text-top;
}

p,
li {
  font-size: 11px;
}

blockquote {
  font-size: 11px;
  font-family: "Lato", Helvetica, Arial, sans-serif;
  font-weight: 400;
  font-style: italic;
  margin: 10px 25px;
}

em {
  color: #999;
}

ul {
  margin: 10px 0 0;
  -webkit-padding-start: 25px;
}

ul li {
  padding-left: 10px;
}

ul.minimal {
  list-style: none;
  padding: 0;
}

ul.minimal li {
  margin-bottom: 3px;
  padding-left: 0;
}

ul.two-column {
  -webkit-column-count: 2;
  -webkit-column-gap: 28px;
  column-count: 2;
  column-gap: 28px;
}

ul.two-column li {
  padding-left: 0;
}

@page {
  size: A4;
}

.container {
  padding-top: 20px;
}

.keyline {
  width: 45px;
  margin: 8px 0 10px;
  border-top: 1px solid #56817A;
}

.pull-left {
  float: left;
}

.pull-right {
  float: right;
}

.clearfix:after {
  content: "";
  display: table;
  clear: both;
}

.profile-pic {
  margin-top: -5px;
  margin-right: 18px;
}

.profile-pic img {
  height: 52px;
  width: 52px;
  border-radius: 50%;
  border: 2px solid #56817A;
}

.summary {
  margin: 5px 0 5px;
}

.sublink {
  font-size: 70%;
  font-weight: 200;
  color: dimgray;
}

.capitalize {
  text-transform: capitalize;
}

/* Layouts */
.page {
  background: white;
  width: 612px;
  min-height: 792px;
  display: block;
  margin: 0 auto;
  border-top: 10px solid #56817A;
  padding: 36px 22px 30px 34px;
  box-shadow: 0 1px 10px rgba(0, 0, 0, 0.5);
}

.page:after {
  content: "";
  display: table;
  clear: both;
}

.left-column {
  float: left;
  width: 160px;
  margin-right: 20px;
  word-wrap: break-word;
}

.right-column {
  width: auto;
  overflow: hidden;
}

.item {
  margin-bottom: 15px;
}

.item:last-child {
  margin-bottom: 0;
}

@media print {
  body {
    margin: 0;
  }

  .page {
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 36px 0 30px;
    box-shadow: none;
  }

  .page .resume-header,
  .page .resume-content {
    padding: 0 22px 0 34px;
  }

  .container {
    page-break-inside: avoid;
  }

  .work-container .item {
    page-break-inside: avoid;
  }

  .fa-external-link {
    display: none;
  }
}

/* Components */
.info-tag-container {
  margin-bottom: 5px;
}

.info-tag-container .fa {
  font-size: 14px;
  width: 12px;
  margin-right: 5px;
  text-align: center;
  vertical-align: middle;
}

.info-tag-container .fa.fa-map-marker {
  font-size: 16px;
}

.info-tag-container .fa.fa-mobile {
  font-size: 18px;
}

.info-tag-container .fa.fa-envelope-o {
  font-size: 12px;
}

.info-tag-container .fa.fa-desktop {
  font-size: 11px;
}

.info-tag-container .fa.fa-external-link {
  width: auto;
  font-size: inherit;
  vertical-align: text-top;
}

.info-tag-container .info-text {
  font-size: 12px;
  text-transform: none;
  display: inline-block;
  vertical-align: middle;
  width: 139px;
}

.references-container .fa {
  font-size: 14px;
}

.education-container .location {
  padding-bottom: 6px;
  font-weight: 400;
}

.education-container .specialization {
  text-transform: none;
  font-style: italic;
}

.flex-container {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
}

.main-skill {
  font-size: 80%;
}

.skill {
  margin: .15em;
  padding: .15em;
  background: ghostwhite;
  border-radius: 5px;
}
`,"src/resume.hbs":`<!doctype html>
<html>

<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, user-scalable=no, minimal-ui">
  <title>{{#resume.basics}}{{name}}{{/resume.basics}}</title>
  <link href="https://maxcdn.bootstrapcdn.com/font-awesome/4.7.0/css/font-awesome.min.css" rel="stylesheet">
  {{{ style }}}
</head>

<body>
  <main id="resume" class="page">
    {{> resume-header}}
    <div class="resume-content">
      <aside class="left-column">
        {{> about }}
        {{> skills }}
        {{> languages }}
        {{> interests }}
      </aside>
      <div class="right-column">
        {{> summary}}
        {{> work }}
        {{> projects }}
        {{> education }}
        {{> volunteer }}
        {{> awards }}
        {{> publications }}
        {{> references }}
      </div>
    </div>
  </main>
</body>

</html>
`,"src/partials/about.hbs":`{{#resume.basics}}
<div class="container about-container">
    {{> title value="About"}}

    {{#if location}}
        {{#location}}
        {{> info-tag text=(formatAddress address city region postalCode countryCode) icon="fa-map-marker"}}
        {{/location}}
    {{/if}}

    {{#if birthday}}
        {{> info-tag text=(concat "Born in " this.birthday) icon="fa-calendar"}}
    {{/if}}

    {{#if email}}
        {{> info-tag text=this.email icon="fa-envelope-o" isEmail=true url=this.email}}
    {{/if}}

    {{#if phone}}
        {{> info-tag text=this.phone icon="fa-mobile"}}
    {{/if}}

    {{#if website}}
        {{> info-tag text=this.website icon="fa-globe" url=this.website}}
    {{/if}}

    {{#if profiles}}
        {{#each profiles}}
            {{> social}}
        {{/each}}
    {{/if}}
</section>
{{/resume.basics}}
`,"src/partials/awards.hbs":`{{#if resume.awards.length}}
<div class="container awards-container">
    {{> title value="Awards"}}

    {{#each resume.awards}}
        <section class="item">
            {{> section-header name=this.title }}

            {{#if awarder}}
            <h5 class="awarder">{{awarder}}</h5>
            {{/if}}

            {{#if summary}}
            <p class="summary">{{summary}}</p>
            {{/if}}
        </section>
    {{/each}}
</div>
{{/if}}`,"src/partials/basics.hbs":`{{#resume.basics}}
	<h1>{{name}}</h1>
	<h2>{{label}}</h2>
	<section id="basics">
		<div class="contact">
		{{#if website}}
		<div class="website">
			<strong>Website</strong>
			{{website}}
		</div>
		{{/if}}
		{{#if email}}
		<div class="email">
			<strong>Email</strong>
			{{email}}
		</div>
		{{/if}}
		{{#if phone}}
		<div class="phone">
			<strong>Phone</strong>
			{{phone}}
		</div>
		{{/if}}
		</div>
		{{#if summary}}
		<div class="summary">
			<p>{{summary}}</p>
		</div>
		{{/if}}
		{{#location}}
		<h3>Location</h3>
		<section id="location">
			{{#if address}}
			<div class="address">
				<strong>Address</strong>
				{{address}}
			</div>
			{{/if}}
			{{#if postalCode}}
			<div class="postalCode">
				<strong>Postal code</strong>
				{{postalCode}}
			</div>
			{{/if}}
			{{#if city}}
			<div class="city">
				<strong>City</strong>
				{{city}}
			</div>
			{{/if}}
			{{#if countryCode}}
			<div class="countryCode">
				<strong>Country code</strong>
				{{countryCode}}
			</div>
			{{/if}}
			{{#if region}}
			<div class="region">
				<strong>Region</strong>
				{{region}}
			</div>
			{{/if}}
		</section>
		{{/location}}
		{{#if profiles.length}}
		<h3>Profiles</h3>
		<section id="profiles">
			{{#each profiles}}
			<div class="item">
				{{#if network}}
				<strong class="network">
					{{network}}
				</strong>
				{{/if}}
				{{#if username}}
				<div class="username">
					{{username}}
				</div>
				{{/if}}
				{{#if url}}
				<div class="url">
					<a href="{{url}}">Link</a>
				</div>
				{{/if}}
			</div>
			{{/each}}
		</section>
		{{/if}}
	</section>
{{/resume.basics}}
`,"src/partials/education.hbs":`{{#if resume.education.length}}
<div class="container education-container">
    {{> title value="Education"}} {{#each resume.education}}
    <section class="item">
        {{> section-header name=this.institution }} {{#if location}}
        <h5 class="location">{{location}}</h5>
        {{/if}}

        <h4>{{#if studyType}}{{studyType}} {{/if}}{{#if area}}{{area}}{{/if}}</h4>

        {{#if gpa}}
        <h5>{{gpa}}</h5>
        {{/if}} {{#if specialization}}
        <h5 class="specialization">{{specialization}}</h5>
        {{/if}} {{#if courses.length}}
        <ul class="two-column">
            {{#each courses}}
            <li>{{.}}</li>
            {{/each}}
        </ul>
        {{/if}}
    </section>
    {{/each}}
</div>
{{/if}}
`,"src/partials/info-tag.hbs":`<div class="info-tag-container">
    {{#if icon}}
    <i class="fa {{icon}}"></i>
    {{/if}}

    {{#if url}}
        <h6 class="info-text">
            <a href="{{#if isEmail}}mailto:{{/if}}{{url}}" target="_blank">
                {{removeProtocol text}}
                {{!-- <i class="fa fa-external-link" aria-hidden="true"></i> --}}
            </a>
        </h6>
    {{else}}
        <h6 class="info-text">{{{text}}}</h6>
    {{/if}}
</div>
`,"src/partials/interests.hbs":`{{#if resume.interests.length}}
    <div class="container interests-container">
        {{> title value="Interests"}}

        {{#each resume.interests}}
            <section class="item">
                {{#if name}}
                    <h4 class="bold">{{name}}</h4>
                {{/if}}
                {{#if keywords.length}}
                    <ul class="minimal">
                        {{#each keywords}}
                            <li>{{.}}</li>
                        {{/each}}
                    </ul>
                {{/if}}
            </section>
        {{/each}}
    </div>
{{/if}}`,"src/partials/languages.hbs":`{{#if resume.languages.length}}
    <div class="container languages-container">
        {{> title value="Languages"}}

        <ul class="minimal">
            {{#each resume.languages}}
                <li>
                    <h6>{{language}} {{#if fluency}}<em>({{fluency}})</em>{{/if}}</h6>
                </li>
            {{/each}}
        </ul>
    </div>
{{/if}}`,"src/partials/projects.hbs":`{{#if resume.projects.length}}
<div class="container project-container">
    {{> title value="Open Source Projects"}}

    {{#each resume.projects}}
        <section class="item">
            {{> section-header name=this.name website=this.url showWebsite=true}}

            {{#if role}}
                <h5>{{role}}</h5>
            {{/if}}

            {{#if keywords.length}}
            <div class="flex-container">
                {{#each keywords}}
                    <h6 class="skill">{{.}}</h6>
                {{/each}}
            </div>
            {{/if}}

            {{#if summary}}
            <p class="summary">{{summary}}</p>
            {{/if}}

            {{#if highlights.length}}
            <ul>
                {{#each highlights}}
                <li>{{.}}</li>
                {{/each}}
            </ul>
            {{/if}}
        </section>
    {{/each}}
</div>
{{/if}}
`,"src/partials/publications.hbs":`{{#if resume.publications.length}}
<div class="container publications-container">
    {{> title value="Publications"}}

    {{#each resume.publications}}
    <section class="item">
        {{> section-header name=this.name}}

        {{#if publisher}}
        <h5 class="awarder">{{publisher}}</h5>
        {{/if}}

        {{#if summary}}
        <p class="summary">{{summary}}</p>
        {{/if}}

    </section>
    {{/each}}
</div>
{{/if}}`,"src/partials/references.hbs":`{{#if resume.references.length}}
<div class="container references-container">
    {{> title value="References"}}

    {{#each resume.references}}
        <section class="item clearfix">
            {{#if reference}}
            <i class="fa fa-quote-left pull-left" aria-hidden="true"></i>
            <blockquote>
                {{reference}}
            </blockquote>
            {{/if}}

            {{#if name}}
            <h5 class="pull-right"> \u2014 {{name}}</h5>
            {{/if}}
        </section>
    {{/each}}
</div>
{{/if}}`,"src/partials/resume-header.hbs":`{{#resume.basics}}
<header class="resume-header clearfix">
    <div class="profile-header pull-left">
        <h1>{{name}}</h1>
        <h2>{{label}}</h2>
    </div>
    <div class="profile-pic pull-right">
        {{#if picture}}
        <img src="{{picture}}" alt="profile-pic">
        {{/if}}
    </div>
</header>
{{/resume.basics}}
`,"src/partials/section-header.hbs":`<div class="section-header clearfix">
    {{#if name}}
    <h3 class="bold pull-left">
        {{#if website}}
            <a href="{{website}}" target="_blank">
                {{name}}
                {{#if showWebsite }}
                    <span class="sublink">\u2219 <a href="{{website}}" target="_blank" class="sublink">{{website}}</a></span>
                {{/if}}
                {{!-- <i class="fa fa-external-link" aria-hidden="true"></i> --}}
            </a>
        {{else}}
            {{name}}
        {{/if}}
    </h3>
    {{/if}}
    <h5 class="italic pull-right">
        {{#if startDate}}
            <span class="startDate">{{formatDate startDate}}</span>
            {{#if endDate}}
            <span class="endDate"> - {{formatDate endDate}}</span>
            {{else}}
            <span class="endDate"> - Present</span>
            {{/if}}
        {{else if releaseDate}}
            {{formatDate releaseDate}}
        {{/if}}
    </h5>
</div>
{{#if description}}
  <h4>
    {{description}}
  </h4>
{{/if}}
`,"src/partials/skills.hbs":`{{#if resume.skills.length}}
    <div class="skills-container">
        {{#each resume.skills}}
            <section class="container">
                {{#if name}}
                    {{> title value=name}}
                {{/if}}
                {{#if level}}
                    <h4 class="bold capitalize">{{level}}</h4>
                {{/if}}
                {{#if keywords.length}}
                    <div class="minimal flex-container">
                        {{#each keywords}}
                            <h6 class="main-skill skill">{{.}}</h6>
                        {{/each}}
                    </div>
                {{/if}}
            </section>
        {{/each}}
    </div>
{{/if}}
`,"src/partials/social.hbs":`{{#if network}}
    {{#if username}}
        {{#if (eq (lowercase network) "linkedin")}}
            {{> info-tag text=(concat '' this.username) icon="fa-linkedin-square" }}
        {{else}}
             {{> info-tag text=this.username icon=(concat "fa-" (lowercase network)) }}
        {{/if}}
    {{/if}}
{{/if}}
`,"src/partials/summary.hbs":`{{#resume.basics}}
    {{#if summary}}
        <div class="container summary-container">
            {{> title value="Summary"}}
            <p class="summary">
                {{summary}}
            </p>
        </div>
    {{/if}}
{{/resume.basics}}`,"src/partials/title.hbs":`<div class="title">
    <h3>{{value}}</h3>
    <div class="keyline"></div>
</div>`,"src/partials/volunteer.hbs":`{{#if resume.volunteer.length}}
<div class="container volunteer-container">
    {{> title value="Volunteer"}}

    {{#each resume.volunteer}}
    <section class="item">
        {{> section-header name=this.organization showWebsite=true}}
        {{#if position}}
        <h5>{{position}}</h5>
        {{/if}}

        {{#if summary}}
        <p class="summary">{{summary}}</p>
        {{/if}}

        {{#if highlights.length}}
        <ul>
            {{#each highlights}}
            <li>{{.}}</li>
            {{/each}}
        </ul>
        {{/if}}
    </section>
    {{/each}}
</div>
{{/if}}
`,"src/partials/work.hbs":`{{#if resume.work.length}}
