            <section class="item">
                {{#if name}}
                    <h4 class="bold">{{name}}</h4>
                {{/if}}
                {{#if keywords.length}}
                    <ul class="minimal">
                        {{#each keywords}}
                            <li>{{.}}</li>
                        {{/each}}
                    </ul>
                {{/if}}
            </section>
        {{/each}}
    </div>
{{/if}}`,languages:`{{#if resume.languages.length}}
    <div class="container languages-container">
        {{> title value="Languages"}}

        <ul class="minimal">
            {{#each resume.languages}}
                <li>
                    <h6>{{language}} {{#if fluency}}<em>({{fluency}})</em>{{/if}}</h6>
                </li>
            {{/each}}
        </ul>
    </div>
{{/if}}`,projects:`{{#if resume.projects.length}}
