        <section class="item">
            {{> section-header name=this.name website=this.url showWebsite=true}}

            {{#if role}}
                <h5>{{role}}</h5>
            {{/if}}

            {{#if keywords.length}}
            <div class="flex-container">
                {{#each keywords}}
                    <h6 class="skill">{{.}}</h6>
                {{/each}}
            </div>
            {{/if}}

            {{#if summary}}
            <p class="summary">{{summary}}</p>
            {{/if}}

            {{#if highlights.length}}
            <ul>
                {{#each highlights}}
                <li>{{.}}</li>
                {{/each}}
            </ul>
            {{/if}}
        </section>
    {{/each}}
</div>
{{/if}}
`,publications:`{{#if resume.publications.length}}
<div class="container publications-container">
    {{> title value="Publications"}}

    {{#each resume.publications}}
    <section class="item">
        {{> section-header name=this.name}}

        {{#if publisher}}
        <h5 class="awarder">{{publisher}}</h5>
        {{/if}}

        {{#if summary}}
        <p class="summary">{{summary}}</p>
        {{/if}}

    </section>
    {{/each}}
</div>
{{/if}}`,references:`{{#if resume.references.length}}
