            <i class="fa fa-quote-left pull-left" aria-hidden="true"></i>
            <blockquote>
                {{reference}}
            </blockquote>
            {{/if}}

            {{#if name}}
            <h5 class="pull-right"> \u2014 {{name}}</h5>
            {{/if}}
        </section>
    {{/each}}
</div>
{{/if}}`,"resume-header":`{{#resume.basics}}
